def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - add empty field if we just finished a comma
            if i > 0 and line[i-1] == ',':
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            field = ''
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        if i < len(line):
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

